import{_ as o,o as t,c,a2 as d}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"中断与异常：IDT、TSS、IST、LAPIC","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/interrupts.md","filePath":"zh/arch/interrupts.md"}'),a={name:"zh/arch/interrupts.md"};function r(i,e,s,n,l,h){return t(),c("div",null,[...e[0]||(e[0]=[d(`<h1 id="中断与异常-idt、tss、ist、lapic" tabindex="-1">中断与异常：IDT、TSS、IST、LAPIC <a class="header-anchor" href="#中断与异常-idt、tss、ist、lapic" aria-label="Permalink to &quot;中断与异常：IDT、TSS、IST、LAPIC&quot;">​</a></h1><p>一切中断形态的东西集中在一处：描述符表、向量映射、带 IST 纪律的 异常分派路径，以及 LAPIC/MSI 层。文件： <code>ocos/kernel/arch/x86_64/arch_idt.{c,h}</code>、<code>arch_idt_stub.S</code>、 <code>arch_idt_load.S</code>、<code>arch_exceptions.{c,h}</code>、<code>arch_irq.{c,h}</code>、 <code>arch_pic.h</code>、<code>arch_lapic.{c,h}</code>、<code>arch_exc_exit.S</code>、 <code>arch_abi_probe.S</code>。</p><h2 id="gdt-tss" tabindex="-1">GDT / TSS <a class="header-anchor" href="#gdt-tss" aria-label="Permalink to &quot;GDT / TSS&quot;">​</a></h2><p>一张 64 字节 GDT（<code>arch_idt.c</code> 中的 <code>arch_gdt_init</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 0 = null          (sel 0x00)</span></span>
<span class="line"><span> 1 = code32        (sel 0x08)  P|ring0|code|RX, 4K|32-bit</span></span>
<span class="line"><span> 2 = data          (sel 0x10)  P|ring0|data|RW</span></span>
<span class="line"><span> 3 = code64        (sel 0x18)  P|ring0|code|RX, 4K|64-bit (L=1)</span></span>
<span class="line"><span> 4 = TSS (16-byte) (sel 0x20)  P|ring0|system|TSS64-available (0x89)</span></span>
<span class="line"><span> 6 = user code64   (sel 0x30, pushed as 0x33 with RPL 3)</span></span>
<span class="line"><span> 7 = user data     (sel 0x38, pushed as 0x3B with RPL 3)</span></span></code></pre></div><p>TSS（<code>arch_tss_t</code>，packed）携带：</p><ul><li><strong>rsp0</strong>——每次任务切换时更新（ring 3 中断入口栈；每个任务的 内核栈顶存于 <code>task_t.rsp0</code>）。</li><li><strong>IST1 = 8 KiB <code>g_panic_stack</code></strong>——由向量 8（#DF）与 18（#MC） 使用。</li><li><strong>IST2 = 8 KiB <code>g_debug_stack</code></strong>——由向量 1（#DB）、2（NMI）、 3（#BP）使用。</li><li><strong>iopb_offset 位于 0x66</strong>（按 SDM 表 8-2），TSS 限界内是 32 字节 全 0xFF 的 IOPB -&gt; <strong>ring 3 对每个端口 [0, 256) 都被拒绝</strong> （PRIV_TEST 根因修复：用户态的 <code>in</code>/<code>out</code> 现在触发异常而非静默 生效）。</li></ul><p><code>arch_load_gdt_idt_tr</code>（<code>arch_idt_load.S</code>）：lgdt + lidt + 段重载 + 远 <code>retfq</code> CS 重载 + <code>ltr 0x20</code>。</p><h2 id="idt" tabindex="-1">IDT <a class="header-anchor" href="#idt" aria-label="Permalink to &quot;IDT&quot;">​</a></h2><p>来自 <code>arch_isr_table</code> 桩数组的 256 个门：选择子 0x18，标志 <strong>0x8E</strong>（P | ring0 | 中断门）——唯有向量 0x80（系统调用）与 向量 3（#BP）取 <strong>0xEE（DPL=3）</strong>，使 ring 3 能 <code>int 0x80</code> / <code>int3</code>。向量 8 与 18 用 IST1；向量 1、2、3 用 IST2。<code>arch_idt_load</code> 还设置 EFER.NXE（MSR 0xC0000080 位 11）。</p><p>桩（<code>arch_idt_stub.S</code>，NASM 宏 x 256）：带 CPU 错误码的向量（8、 10、11、12、13、14、17、30）跳过伪错误码压栈；公共路径压 15 个 GPR，执行 <code>cld</code>（BUG-0138——ABI 要求 C 入口处 DF=0），在 <code>call arch_isr_dispatch</code> 前后把栈动态对齐到 16 字节（BUG-0137）， 最后 <code>iretq</code>。</p><h2 id="向量映射" tabindex="-1">向量映射 <a class="header-anchor" href="#向量映射" aria-label="Permalink to &quot;向量映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>向量</th><th>用途</th><th>EOI</th></tr></thead><tbody><tr><td>0..31</td><td>CPU 异常 -&gt; <code>arch_exc_dispatch</code></td><td>-</td></tr><tr><td>32..47（0x20..0x2F）</td><td>8259 PIC IRQ0..15 -&gt; <code>arch_irq_dispatch</code></td><td>提前 EOI</td></tr><tr><td>48..111（0x30..0x6F）</td><td>MSI/MSI-X -&gt; <code>arch_msi_dispatch</code></td><td>LAPIC EOI</td></tr><tr><td>128（0x80）</td><td>系统调用（DPL=3）-&gt; <code>core_syscall_dispatch</code></td><td>-</td></tr><tr><td>0xFF</td><td>LAPIC 伪中断（计数后丢弃）</td><td>-</td></tr></tbody></table><p>两片 8259 被重映射，使 IRQ0-15 落在向量 32-47。LAPIC 以 xAPIC 方式启用（MMIO 位于 0xFEE00000），带 EOI、自 IPI 与 MSI/MSI-X 向量分派 0x30..0x6F（每向量 4 个处理器槽位）；<code>msitest</code> 布防真实 的 e1000 MSI 并统计 LAPIC 向量命中（见 <a href="./driver-model.html">driver-model.md</a>）。PIC 与 MSI 两条路径上的 <strong>提前 EOI 策略</strong>之所以存在，是为了让处理器内的上下文切换绝不 会卡死中断控制器。</p><p>异常名（<code>arch_exc_names[32]</code>）：<code>&quot;#DE Divide Error&quot;</code>、<code>&quot;#DB Debug&quot;</code>、<code>&quot;NMI Non-Maskable Interrupt&quot;</code>、<code>&quot;#BP Breakpoint&quot;</code>、 <code>&quot;#OF Overflow&quot;</code>、<code>&quot;#BR Bound Range Exceeded&quot;</code>、<code>&quot;#UD Invalid Opcode&quot;</code>、<code>&quot;#NM Device Not Available&quot;</code>、<code>&quot;#DF Double Fault&quot;</code>、 <code>&quot;#TS Invalid TSS&quot;</code>、<code>&quot;#NP Segment Not Present&quot;</code>、<code>&quot;#SS Stack-Segment Fault&quot;</code>、<code>&quot;#GP General Protection&quot;</code>、<code>&quot;#PF Page Fault&quot;</code>、…… <code>&quot;#MF x87 FPU&quot;</code>、<code>&quot;#AC Alignment Check&quot;</code>、<code>&quot;#MC Machine Check&quot;</code>、<code>&quot;#XF SIMD FP&quot;</code>、<code>&quot;#SX Security Exception&quot;</code>。</p><h2 id="注册接口" tabindex="-1">注册接口 <a class="header-anchor" href="#注册接口" aria-label="Permalink to &quot;注册接口&quot;">​</a></h2><ul><li>异常：<code>arch_exc_register_handler(vector, handler)</code>——每向量最多 4 个处理器（<code>OC_EXC_CHAIN_LEN 4</code>），最近注册者最先运行；返回 1 的处理器认领该异常，执行随之恢复。</li><li>IRQ：<code>arch_irq_register_handler(irq 0..15, fn, ctx)</code>——每 IRQ 4 个槽位，自动解除 PIC 屏蔽；注销时压缩，空则重新屏蔽。</li><li>MSI：<code>arch_lapic_register_vector(0x30..0x6F, fn, ctx)</code>。</li><li>缺页：<code>mem_vmm_register_fault_handler(fn)</code>——最多 4 个 （见 <a href="./memory.html">memory.md</a>）。</li><li>按向量计数器（<code>arch_irq_counts[256]</code> / <code>arch_exc_counts[256]</code>） 支撑 <code>exc</code> 与 <code>irqabitest</code> 诊断。</li></ul><h2 id="异常分派-arch-exc-dispatch" tabindex="-1">异常分派（<code>arch_exc_dispatch</code>） <a class="header-anchor" href="#异常分派-arch-exc-dispatch" aria-label="Permalink to &quot;异常分派（\`arch_exc_dispatch\`）&quot;">​</a></h2><ol><li><strong>嵌套 #PF 守卫</strong>：在处理 #PF 期间再次触发的 #PF 仅经串口打印 <code>*** NESTED #PF INSIDE EXCEPTION HANDLER - HALTING ***</code> 并 cli;hlt 永久停机。</li><li>L1 处理器链（按注册的逆序）。</li><li>#PF -&gt; <code>mem_vmm_handle_page_fault</code>（栈增长等）；若已处理则恢复 执行。</li><li>串口转储：<code>*** EXCEPTION &lt;v&gt;: &lt;name&gt; ***</code>，附 error_code/rip/ cs/rflags/rsp/ss（#PF 另加 cr2）。</li><li><strong>ring 3 来源</strong>（<code>cs &amp; 3 == 3</code>）：尝试投递 SIGSEGV（有处理器 + 不在处理器内 + 已投递 &lt; 3 次；恢复器跳板 <code>mov eax,42; int 0x80; hlt</code> 写在栈上 stack_base+0x400 处，BUG-0277）；失败或耗尽时： crashlog 记录 + <code>*** KILLING user process (pid=N) due to exception V, kernel continues ***</code>、统一收割、唤醒父进程、 TASK_EXITED、yield。<strong>向量 1/2/3 的击杀在专用退出栈上运行</strong>—— 见下文 IST 纪律。</li><li><strong>ring 0 来源</strong> -&gt; 带栈溢出归因的 panic：CR2 落在任务守卫页内的 <code>#PF</code> -&gt; <code>&quot;KERNEL STACK OVERFLOW (guard page hit, task=&lt;name&gt;)&quot;</code>； rsp 位于任务栈底或之下、或为不可信垃圾值（&gt;= 0x40000000000）的 <code>#DF</code> -&gt; <code>&quot;KERNEL STACK OVERFLOW (stack exhausted -&gt; #DF, task=&lt;name&gt;)&quot;</code>；否则 <code>&quot;ring-0 exception &lt;v&gt; (&lt;name&gt;)&quot;</code>。-&gt; <code>kernel_panic_frame(reason, f)</code>（见 <a href="./crash-recovery.html">crash-recovery.md</a>）。</li></ol><h2 id="ist-纪律-你看不见的那部分" tabindex="-1">IST 纪律（你看不见的那部分） <a class="header-anchor" href="#ist-纪律-你看不见的那部分" aria-label="Permalink to &quot;IST 纪律（你看不见的那部分）&quot;">​</a></h2><p>IST1/IST2 给了 #DF/#MC/#DB/NMI/#BP 别的东西碰不到的栈——但这 带来一条约束：调度器绝不能把 rsp 保存在 IST2 <em>之内</em>。在向量 1/2/3 上执行的 ring 3 击杀恰恰会那样做（从 IST2 帧里 reap + yield）。 修复（BUG-0139，<code>arch_exc_exit.S</code>）： <code>arch_exc_run_on_exit_stack()</code> 在 reap+yield <em>之前</em>切换到专用 8 KiB 退出栈，因此 IST2 绝不会被挂起或恢复。同族纪律：<code>#DF</code> panic 路径完全在分派器深度运行，只用一个静态 192 字节串口行缓冲——#DF 无记录、无转储、无刷新（已在 KNOWN_ISSUES 中声明），因为按定义 机器已经在其最后一张栈上了。</p><h2 id="abi-探针-arch-abi-probe-s" tabindex="-1">ABI 探针（<code>arch_abi_probe.S</code>） <a class="header-anchor" href="#abi-探针-arch-abi-probe-s" aria-label="Permalink to &quot;ABI 探针（\`arch_abi_probe.S\`）&quot;">​</a></h2><p><code>irqabitest</code> 布防 <code>g_arch_irq_entry_probe</code>——<code>arch_isr_dispatch</code> 的第一个动作即跳到该探针，验证 C 分派入口处 rsp 为 8 mod 16（计入 被压入的调用返回地址后的 SysV 对齐规则）且 DF 为 0，累积结果位并 自愈 DF。这是对上文 BUG-0137/0138 对齐/cld 修复的回归测试——桩 与 C 世界之间的 ABI 契约是<em>被测试的</em>，不是被假设的。</p><h2 id="定时器管道" tabindex="-1">定时器管道 <a class="header-anchor" href="#定时器管道" aria-label="Permalink to &quot;定时器管道&quot;">​</a></h2><p>PIT（8253/8254 ch0 @ 100 Hz，除数 11932，模式 2，端口 0x40/0x43） 引发 IRQ0；<code>core_timer.c</code> 递增 tick/毫秒计数器并运行 16 槽位软 定时器表（周期 + 单次，回调在 IRQ 上下文中）。节拍消费者：调度器 时间片、网络栈的 10 毫秒轮询、health 采样器的 1 秒、看门狗检查、 引导状态心跳（见 <a href="./scheduler.html">scheduler.md</a>、 <a href="./network-stack.html">network-stack.md</a>）。HPET 中断（受测时）走 <strong>legacy 路由 timer1 -&gt; IRQ8</strong>，因为内核只驱动两片 PIC——timer0 会与 PIT 在 IRQ0 上相撞，故从不启用。RTC 的 UIE/PIE/AIE 也经链表 共享 IRQ8。</p><h2 id="s3-挂起往返" tabindex="-1">S3 挂起往返 <a class="header-anchor" href="#s3-挂起往返" aria-label="Permalink to &quot;S3 挂起往返&quot;">​</a></h2><p><code>arch_acpi_s3.S</code> 把 RSP/CR3/CR4/CR0 保存进固定的低内存保存区 （偏移 0x200/0x208/0x20C/0x210）并写 PM1a_CNT 的 SLP_TYP|SLP_EN。<code>arch_acpi_s3_resume.S</code> 是 16/32 位恢复跳板：恢复 控制寄存器、重入长模式、恢复 RSP、返回 C 调用者。固件复位之后： <code>arch_irq_rearm</code>（PIC）、<code>core_timer_resume</code>（PIT）、 <code>driver_pci_restore_commands</code>（每设备恢复 IO+MEM+BUS_MASTER）以及 e1000e 寄存器重放——见 <a href="./driver-model.html">driver-model.md</a>。</p>`,27)])])}const u=o(a,[["render",r]]);export{p as __pageData,u as default};
